--
-- Name: mv_daily_pnl; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_daily_pnl AS
 SELECT user_id,
    date(entry_time) AS trade_date,
    count(*) AS trade_count,
    sum(pnl_r) AS total_r,
    sum(
        CASE
            WHEN (pnl_r > (0)::numeric) THEN 1
            ELSE 0
        END) AS wins,
    sum(
        CASE
            WHEN (pnl_r < (0)::numeric) THEN 1
            ELSE 0
        END) AS losses,
    round(avg(pnl_r), 4) AS avg_r
   FROM public.trades
  WHERE ((status)::text = 'closed'::text)
  GROUP BY user_id, (date(entry_time))
  WITH NO DATA;


--
-- Name: mv_performance_by_pair; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_performance_by_pair AS
 SELECT user_id,
    pair,
    count(*) AS trades,
    round(avg(
        CASE
            WHEN (pnl_r > (0)::numeric) THEN 100.0
            ELSE (0)::numeric
        END), 1) AS win_rate_pct,
    round(sum(pnl_r), 2) AS net_r,
    round(avg(pnl_r), 3) AS avg_r
   FROM public.trades
  WHERE ((status)::text = 'closed'::text)
  GROUP BY user_id, pair
  WITH NO DATA;


--
-- Name: mv_rolling_performance; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_rolling_performance AS
 SELECT user_id,
    count(*) AS total_trades,
    round(avg(
        CASE
            WHEN (pnl_r > (0)::numeric) THEN 100.0
            ELSE (0)::numeric
        END), 1) AS win_rate_pct,
    round(sum(pnl_r), 2) AS net_r,
    round(avg(pnl_r), 3) AS expectancy_r,
    max(pnl_r) AS best_trade_r,
    min(pnl_r) AS worst_trade_r,
    now() AS last_updated
   FROM public.trades
  WHERE (((status)::text = 'closed'::text) AND (entry_time >= (now() - '30 days'::interval)))
  GROUP BY user_id
  WITH NO DATA;


